import{u as i,o,c as r,j as t,k as n,F as u,a8 as l,e as h,p as c}from"./chunks/framework.fPNBP_58.js";const d=["markdown-url"],q={"data-allow-mismatch":"",style:{display:"none"}},b=JSON.parse('{"title":"Climate Change Explorer for Tourism","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"ccet-use-case-2","file":"https://gtif-austria.github.io/public-narratives/ccet-use-case-2.md","title":"Climate Change Explorer for Tourism"},"relativePath":"narratives/ccet-use-case-2.md","filePath":"narratives/[narrative].md"}'),p={name:"narratives/ccet-use-case-2.md"},v=Object.assign(p,{setup(m){const e=c(!0);e.value=!1;const{params:s}=i();return(g,a)=>(o(),r("div",null,[t("client-only",null,[t("eox-storytelling",{"show-nav":"","markdown-url":n(s).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,d)]),t("div",q,[e.value?(o(),r(u,{key:0},[a[0]||(a[0]=l(' --- cover-image: https://raw.githubusercontent.com/GTIF-Austria/public-narratives/a119e16f897695fb696bb1d963ff901183c7332e/assets/MichaelaLandauer/CCETUC-2Climate-threats-1790866217063.jpg domain: Climate Change &amp; Tourism provider: GeoVille,Austria Tourism --- <h1 id="climate-change-explorer-for-tourism" tabindex="-1">Climate Change Explorer for Tourism <a class="header-anchor" href="#climate-change-explorer-for-tourism" aria-label="Permalink to &quot;Climate Change Explorer for Tourism &lt;!--{ as=&quot;img&quot; mode=&quot;hero&quot; src=&quot;https://raw.githubusercontent.com/GTIF-Austria/public-narratives/a119e16f897695fb696bb1d963ff901183c7332e/assets/MichaelaLandauer/CCETUC-2Climate-threats-1790866217063.jpg&quot; }--&gt;&quot;">​</a></h1><h3 id="use-case-2-climate-hazards" tabindex="-1">Use Case 2 - Climate Hazards <a class="header-anchor" href="#use-case-2-climate-hazards" aria-label="Permalink to &quot;Use Case 2 - Climate Hazards&quot;">​</a></h3><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Climate Change Explorer for Tourism (CCET) is a joint initiative by <a href="https://www.geoville.com/" target="_blank" rel="noreferrer"><strong>GeoVille</strong></a>, <a href="https://b2b.austria.info/de-at/" target="_blank" rel="noreferrer"><strong>Österreich Werbung</strong></a>, <a href="https://eox.at/" target="_blank" rel="noreferrer"><strong>EOX</strong></a> and <a href="https://www.brz.gv.at/" target="_blank" rel="noreferrer"><strong>BRZ</strong></a> within Digital Twin Austria (GTIF-AT EA), giving Austria&#39;s tourism regions a user-friendly picture of climate change impacts and hazards. This page looks at the second of three use cases showcased in the tool.</p><h2 id="what-use-case-2-is-about" tabindex="-1">What Use Case 2 is about <a class="header-anchor" href="#what-use-case-2-is-about" aria-label="Permalink to &quot;What Use Case 2 is about&quot;">​</a></h2><p>This use case assesses the increasing exposure of tourism destinations to climate-related hazards – in other words, how vulnerable a given destination is becoming as the climate changes. In this use case, the term “threat” refers to the impact of temperature changes for tourism. In the scope of the project, snow loss has been assessed as one example of these threats. The development of this indicator aims at completing those provided by the <a href="https://hora.gv.at/#/chwrz:-/bgrau/a-/@47.72463,13.50823,8z" target="_blank" rel="noreferrer"><strong>Platform HORA</strong></a> of the BMLUK, already assessing natural hazards and risks all over Austria.</p><p><strong>Explore the Climate Hazards dataset <a href="https://gtif-austria.info/explore?indicator=tourism_uc2_stats" target="_blank" rel="noreferrer">HERE</a>.</strong></p><h2 id="exploring-climate-hazards-in-austria" tabindex="-1">Exploring Climate Hazards in Austria <a class="header-anchor" href="#exploring-climate-hazards-in-austria" aria-label="Permalink to &quot;Exploring Climate Hazards in Austria &lt;!--{ as=&quot;eox-map&quot; mode=&quot;tour&quot; position=&quot;right&quot; }--&gt;&quot;">​</a></h2><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&lt;!--{ layers=&#39;[{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;geoland_base;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Geoland Basemap&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://mapsneu.wien.gv.at/basemap/geolandbasemap/normal/google3857/{z}/{y}/{x}.png&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ Datenquelle: &lt;a href=\\&quot;https://basemap.at\\&quot; target=\\&quot;_blank\\&quot; property=\\&quot;dct:title\\&quot;&gt;basemap.at&lt;/a&gt; }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}},{&quot;type&quot;:&quot;VectorTile&quot;,&quot;declutter&quot;:true,&quot;properties&quot;:{&quot;id&quot;:&quot;tourism_uc2_stats;:;2030-01-01T00:00:00Z;:;Climate Hazards Statistics;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Climate Hazards Statistics&quot;},&quot;source&quot;:{&quot;type&quot;:&quot;VectorTile&quot;,&quot;format&quot;:{&quot;type&quot;:&quot;MVT&quot;},&quot;url&quot;:&quot;https://eoapi.workspace.gtif-eox.hub-otc.eox.at/vector/collections/public.tourism_risk_stats_new/tiles/WebMercatorQuad/{z}/{x}/{y}&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;},&quot;style&quot;:{&quot;tooltip&quot;:[{&quot;id&quot;:&quot;tourism_region&quot;,&quot;title&quot;:&quot;Tourism Region&quot;}],&quot;fill-color&quot;:[244,166,184,0.5],&quot;stroke-color&quot;:&quot;black&quot;,&quot;stroke-width&quot;:1.5,&quot;variables&quot;:{&quot;vmin&quot;:0,&quot;vmax&quot;:10,&quot;scenario&quot;:&quot;rcp45&quot;,&quot;selected_metric&quot;:&quot;hot_days&quot;,&quot;decade&quot;:&quot;2051_2060&quot;,&quot;aggregation&quot;:&quot;mean&quot;,&quot;month&quot;:&quot;jul&quot;,&quot;selected_elevation&quot;:&quot;full&quot;,&quot;combined_prop&quot;:&quot;full_jul_mean&quot;}}},{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;overlay_bright;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Overlay labels&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/overlay_base_bright_3857/default/g/{z}/{y}/{x}.png&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ Overlay: Data &amp;copy; &lt;a href=\\&quot;http://www.openstreetmap.org/copyright\\&quot; target=\\&quot;_blank\\&quot;&gt;OpenStreetMap&lt;/a&gt; contributors, Made with Natural Earth, Rendering &amp;copy; &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX&lt;/a&gt; }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}}]&#39; zoom=&quot;7.560557146816587&quot; center=[14.547234215383504,48.10443376958361] projection=&quot;&quot; animationOptions={duration:500}}--&gt;&quot;">​</a></h3><h4 id="climate-hazards" tabindex="-1">Climate Hazards <a class="header-anchor" href="#climate-hazards" aria-label="Permalink to &quot;Climate Hazards&quot;">​</a></h4><p>Explore Climate Hazards such as snow decline, flood and avalche risk in Austria.</p><h2 id="the-data-behind-it" tabindex="-1">The data behind it <a class="header-anchor" href="#the-data-behind-it" aria-label="Permalink to &quot;The data behind it&quot;">​</a></h2><p>The data for Use Case 2 come from two different sources:</p><p><strong>1. SNOWGRID-CL dataset</strong></p><p>The data for snow depth comes from the public dataset <a href="https://data.hub.geosphere.at/dataset/snowgrid_cl-v2-1d-1km" target="_blank" rel="noreferrer">SNOWGRID-CL dataset</a> owned by GeoSphere Austria providing daily updated analyses of daily snow depth and snow water equivalent (SWE) on a 1x1 km grid covering all of Austria since 01.01.1961.</p><p>Average snow depth between November and April across Austria is compared between a historical reference period (1961–1990) and recent years (2011–2026) at a spatial resolution of 1 km. For each location, the snow depth anomaly is calculated as both an absolute change in centimeters and a percentage change relative to the historical average.</p><p>The layer “snow depth changes” shows the percentage of recent gain or loss of snow depth in centimeters.</p><p><strong>2. HORA</strong></p><ul><li><p><strong>Flood risk</strong>: “The ‘flood risk zoning’ map shows those areas at risk from 30-year, 100-year and 300-year flood events. It should be noted that flood defences (particularly those recently constructed) are not taken into account across the entire area.</p></li><li><p><strong>Avalanche risk</strong>: The risk posed by avalanches is defined in so-called hazard zone plans, which are drawn up by the Austrian Torrent and Avalanche Control Authority. The hazard zone plan (GZP) is a comprehensive assessment of the risks posed by torrents, avalanches and erosion. It forms the basis for planning protective measures and for assessing their urgency. It supports the building authorities, local and regional spatial planning, and serves the purposes of public safety.</p></li><li><p><strong>Hot days</strong>: The figures shown represent the average number of days per year during the 1991–2020 climate period. Data source: SPARTACUS (Spatiotemporal Reconstruction Dataset of Climate in Austria)</p></li><li><p><strong>Heat episodes</strong>: A heatwave according to Kysely (Kysely episode) is identified as soon as the maximum temperature exceeds 30 °C on at least three consecutive days and persists for as long as the average maximum temperature over the entire episode remains above 30 °C and the maximum temperature on any given day does not fall below 25 °C. The figure given is the total number of days falling within a Kysely episode. Data source: SPARTACUS (Spatiotemporal Reconstruction Dataset of Climate in Austria)</p></li></ul><h2 id="benefit-for-users" tabindex="-1">Benefit for users <a class="header-anchor" href="#benefit-for-users" aria-label="Permalink to &quot;Benefit for users&quot;">​</a></h2><p>Tourism regions gain a long-term, evidence-based picture of climate hazards across the whole region, supporting decisions on adapting tourism infrastructure.</p><p>Individual destinations can see, cell by cell, how far their local snow cover has already declined – valuable evidence for decisions on snowmaking, resource planning and diversification into snow-independent offerings.</p><p>As further hazards such as flooding, avalanches or heat stress are added, destinations will increasingly be able to weigh up several climate hazards together, rather than assessing each in isolation.</p><p><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/7c50b4e38227260c495eeb622ac4379d2c9cf52d/assets/MichaelaLandauer/Bild-6-1793798933282.png" alt="Bild (6).png"> Using the SNOWGRID-CL and HORA datasets, users can compare several Austrian destinations in terms of the risk of snow decline, avalanches or flooding.</p>',25))],64)):h("",!0)])]))}});export{b as __pageData,v as default};
